import{_ as a,o,c as i,aa as t}from"./chunks/framework.BAs_AphD.js";const p=JSON.parse('{"title":"Cookies v aplikaci Buildary.online","description":"","frontmatter":{"title":"Cookies v aplikaci Buildary.online","wiki":"cs:diary:cookies"},"headers":[],"relativePath":"diary/cookies.md","filePath":"diary/cookies.md","lastUpdated":1794209661000}'),r={name:"diary/cookies.md"};function n(s,e,l,u,c,d){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="cookies-v-aplikaci-buildary-online" tabindex="-1">Cookies v aplikaci Buildary.online <a class="header-anchor" href="#cookies-v-aplikaci-buildary-online" aria-label="Permalink to &quot;Cookies v aplikaci Buildary.online&quot;">​</a></h1><p>Jako většina webů používá i aplikace Buildary.online cookies – malé soubory, které web ukládá do počítače uživatele. Díky nim si aplikace pamatuje informace, které vám usnadní její další používání.</p><h2 id="jake-cookies-buildary-pouziva" tabindex="-1">Jaké cookies Buildary používá <a class="header-anchor" href="#jake-cookies-buildary-pouziva" aria-label="Permalink to &quot;Jaké cookies Buildary používá&quot;">​</a></h2><p>Aplikace používá technické cookies, které jsou nezbytné pro správný chod služby.</p><ul><li>Pokud aplikace běží na infrastruktuře zákazníka (on-premise, tedy provoz na vlastním serveru zákazníka, například ve skupině ČEZ), používá <strong>jen technické cookies</strong>.</li><li>Pokud aplikace běží jako veřejně dostupná služba, používá navíc cookies nástroje <strong>Google Analytics</strong>, který vytváří anonymní statistiky přístupů.</li></ul><table tabindex="0"><thead><tr><th>Cookie</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><code>.AuthScheme</code></td><td>název autentizačního schématu při přihlášení přes server třetí strany</td></tr><tr><td><code>.idsrv.session</code></td><td>identifikátor relace (session), umožňuje rozpoznat její změnu</td></tr><tr><td><code>.AspNetCore.Identity.Application</code></td><td>autorizační cookie při prodlužování přihlašovacího tokenu</td></tr></tbody></table><h2 id="osobni-udaje" tabindex="-1">Osobní údaje <a class="header-anchor" href="#osobni-udaje" aria-label="Permalink to &quot;Osobní údaje&quot;">​</a></h2><p>Aplikace neshromažďuje ani neodesílá žádné osobní informace o uživatelích a je plně v souladu s GDPR. Podrobnosti o ochraně osobních údajů jsou ve Všeobecných obchodních podmínkách nebo v individuálních smlouvách s jednotlivými zákazníky.</p><h2 id="zrusit-ucet" tabindex="-1">Zrušit účet <a class="header-anchor" href="#zrusit-ucet" aria-label="Permalink to &quot;Zrušit účet&quot;">​</a></h2><p>Pokud chcete Buildary přestat používat a zrušit svůj účet, napište nám na <a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a>. Viz také <a href="/buildary-help-preview/firstofall/account#zrusit-ucet">Správa účtu</a>.</p><h2 id="system-esd-pro-cez-distribuci" tabindex="-1">Systém ESD pro ČEZ Distribuci <a class="header-anchor" href="#system-esd-pro-cez-distribuci" aria-label="Permalink to &quot;Systém ESD pro ČEZ Distribuci&quot;">​</a></h2><ul><li><strong>Cookies</strong>: viz <a href="https://www.cezdistribuce.cz/cs/informace-o-webu/cookies" target="_blank" rel="noreferrer">informace o cookies na webu ČEZ Distribuce</a>.</li><li><strong>Zrušení účtu</strong>: pokud chcete ESD přestat používat a zrušit svůj účet, kontaktujte helpdesk skupiny ČEZ.</li></ul>',12)])])}const h=a(r,[["render",n]]);export{p as __pageData,h as default};
